impl Solution{pub fn is_match(s:String,p:String)->bool{let(s,p)=(s.as_bytes(),p.as_bytes());let(mut i,mut j,mut star,mut mark)=(0usize,0usize,None,0usize);while i<s.len(){if j<p.len()&&(p[j]==b'?'||p[j]==s[i]){i+=1;j+=1}else if j<p.len()&&p[j]==b'*'{star=Some(j);j+=1;mark=i}else if let Some(x)=star{j=x+1;mark+=1;i=mark}else{return false}}while j<p.len()&&p[j]==b'*'{j+=1}j==p.len()}}
